/* @lc app=leetcode id=3320 lang=kotlin */ class Solution { fun countWinningSequences(s: String): Int = s.length.let { n -> (2 * n + 1).let { W -> 1_000_000_007L.let { M -> s.fold(Array(4) { LongArray(W) }.also { it[3][n] = 1L }) { dp, ch -> "FWE".indexOf(ch).let { a -> Array(4) { LongArray(W) }.also { nd -> (0..3).forEach { l -> (0..2).filter { it != l }.forEach { b -> ((b - a + 3) % 3).let { r -> (if (r == 1) 1 else if (r == 2) -1 else 0).let { dl -> (0 until W).forEach { d -> if (dp[l][d] != 0L && d + dl in 0 until W) nd[b][d + dl] = (nd[b][d + dl] + dp[l][d]) % M } } } } } } } }.let { dp -> (0..2).sumOf { l -> (n + 1 until W).sumOf { dp[l][it] } } % M }.toInt() } } } }